<style>body{font-family:Tahoma,Arial,sans-serif;color:#252238;background:#f5f5f7;margin:0}.report{max-width:210mm;min-height:297mm;margin:16px auto;background:#fff;padding:16mm;box-sizing:border-box}.head{display:flex;justify-content:space-between;gap:12px;border-bottom:2px solid #5b4b8a;padding-bottom:12px}.head h1{font-size:21px;margin:0 0 5px}.head p{margin:0;color:#6d6877}.logo{max-width:72px;max-height:72px;object-fit:contain}.meta{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin:16px 0}.meta div{border:1px solid #e4e0ed;border-radius:8px;padding:8px}.meta span{display:block;color:#736d80;font-size:11px}.meta strong{display:block;margin-top:3px}.group{margin:18px 0 8px;font-size:14px;border-right:4px solid #5b4b8a;padding:5px 8px;background:#f6f4fa}table{width:100%;border-collapse:collapse;font-size:12px}th{background:#f0edf7;color:#342c52}th,td{border:1px solid #ddd7e7;padding:7px;text-align:right;vertical-align:top}.note{white-space:pre-wrap;line-height:1.6}.print{margin:16px;text-align:center}.print button{padding:8px 20px}@media print{body{background:#fff}.report{margin:0;max-width:none;padding:10mm}.print{display:none}@page{size:A4;margin:0}}</style>
